draw:
var g = 9.8, Hh = p.height, u = p.u;
var tm = Hh / u;
var tland = Math.sqrt(2 * Hh / g);
var ymeet = Hh - 0.5 * g * tm * tm;
var pad = 26;
var groundY = H - pad;
var sc = (groundY - pad) / (Hh * 1.05);
function Y(y) { return groundY - y * sc; }
var xa = W * 0.34, xb = W * 0.56;

var stop = tm < tland ? tm : tland;
var cyc = stop + 1.0;
var now = t % cyc;
var tt = now < stop ? now : stop;

var yA = Hh - 0.5 * g * tt * tt;
var yB = u * tt - 0.5 * g * tt * tt;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(10, groundY); ctx.lineTo(W - 10, groundY); ctx.stroke();

ctx.setLineDash([3, 4]); ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(10, Y(Hh)); ctx.lineTo(W - 10, Y(Hh)); ctx.stroke();
if (ymeet > 0) {
  ctx.beginPath(); ctx.moveTo(10, Y(ymeet)); ctx.lineTo(W - 10, Y(ymeet)); ctx.stroke();
}
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("drop from " + Hh.toFixed(0) + " m", 12, Y(Hh) - 6);
if (ymeet > 0) { ctx.fillText("they meet at " + ymeet.toFixed(1) + " m", 12, Y(ymeet) - 6); }

/* gap bar: the separation closes at the constant rate u */
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(W - 34, Y(yA)); ctx.lineTo(W - 34, Y(yB)); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText((yA - yB).toFixed(1) + " m apart", W - 120, (Y(yA) + Y(yB)) / 2 - 6);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(xa, Y(yA), 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(xb, Y(yB > 0 ? yB : 0), 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("dropped", xa - 24, Y(yA) - 12);
ctx.fillText("thrown up at " + u.toFixed(0) + " m/s", xb + 12, Y(yB > 0 ? yB : 0) + 4);

out.note = "gap = " + Hh.toFixed(0) + " - " + u.toFixed(0) + "t, so they meet at t = " +
  tm.toFixed(2) + " s and height " + (ymeet > 0 ? ymeet.toFixed(1) + " m" : "ground level or below");
